// wf.intake.photos > "Request": one uploaded photo -> Media service (validate, EXIF, hashes, blur).
// The cleaned copy goes to media/<listing>/<upload>.jpg; the raw upload is deleted by the caller afterwards.
const x = $input.first().json;
return [{ json: { ...x, url: `${String(x.media_url).replace(/\/+$/, '')}/v1/images/process`,
  body: { source_key: x.key, output_key: `media/${x.listing_id}/${x.upload_id}.jpg`, blur: true } } }];

// wf.intake.photos > "Outcome": what the Media service answered.
//   200 -> store; 422 -> reject (the reason code from the service); 404 -> not uploaded yet (left pending);
//   anything else (503, timeout, connection refused) -> transient: the job is retried later (spec 5.6).
const req = $('Request').first().json;
const r = $input.first().json || {};
const status = r.statusCode || 0;
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
const base = { upload_id: req.upload_id, key: req.key };
if (status === 200 && body && body.sha256) return [{ json: { ...base, action: 'store', report: body } }];
if (status === 422) {
  const issue = (body && body.error && body.error.details && body.error.details[0] && body.error.details[0].issue) || 'INVALID';
  return [{ json: { ...base, action: 'reject', code: issue, message: (body && body.error && body.error.message) || 'rejected by the media service' } }];
}
if (status === 404) return [{ json: { ...base, action: 'missing' } }];
return [{ json: { ...base, action: 'transient', code: 'MEDIA_SERVICE', message: `media service answered ${status || r.code || 'nothing'}` } }];

// wf.intake.photos > "Result": one line per upload for the job output.
const o = $('Outcome').first().json;
const db = $input.first().json || {};
if (o.action === 'store') {
  const r = db.r || {};
  if (r.ok) {
    const rep = o.report;
    return [{ json: { upload_id: o.upload_id, key: o.key, status: 'processed', media_id: r.media_id,
      near_duplicates: r.near_duplicates || [], blur: rep.blur.counts, sharpness: rep.metrics.sharpness,
      has_gps: !!(rep.exif && rep.exif.has_gps), ms: rep.timings && rep.timings.total_ms } }];
  }
  return [{ json: { upload_id: o.upload_id, key: o.key, status: 'rejected', error_code: r.error_code || 'STORE_FAILED' } }];
}
if (o.action === 'reject') return [{ json: { upload_id: o.upload_id, key: o.key, status: 'rejected', error_code: o.code } }];
if (o.action === 'missing') return [{ json: { upload_id: o.upload_id, key: o.key, status: 'missing' } }];
return [{ json: { upload_id: o.upload_id, key: o.key, status: 'transient', error_code: o.code, error: o.message } }];
